import json,shutil,html,statistics,hashlib,os
from pathlib import Path
r=Path(__file__).resolve().parents[1];out=Path(os.environ.get('FY27_REVIEW_OUTPUT',r/'evidence/v27-review'));data=out/'data';data.mkdir(exist_ok=True)
read=lambda p:json.loads((r/p).read_text())
for p in (r/'source/v27').glob('*.json'):shutil.copy2(p,data/p.name)
shutil.copy2(r/'source/v27/equipment-inventory.csv',data/'equipment-inventory.csv')
for src,name in [('evidence/v27-movement.json','movement.json'),('evidence/v27-dog-movement.json','dog-movement.json'),('evidence/v27-B-elevator-rides.json','B-elevator-rides.json'),('evidence/v27-input-controls.json','input-controls.json'),('evidence/v27-catalog-api.json','catalog-api.json'),('evidence/v27-reference-scene-keys.json','reference-scene-keys.json'),('evidence/v25-retail-physics.json','retail-physics.json'),('evidence/v25-equipment-retained.json','equipment-approaches.json'),('evidence/v27-architecture.json','architecture.json'),('evidence/v27-landscape-reconcile.json','landscape-reconcile.json')]:
 if (r/src).exists():shutil.copy2(r/src,data/name)
inv=read('source/v27/equipment-inventory.json');changes=read('source/v27/changed-equipment.json');cams=read('source/v27/review-cameras.json');esc=lambda v:html.escape(str(v))
labels={'below':'真下から見上げ','oblique':'斜め下45°','side':'横から','boarding':'乗降口','upper':'上階踊り場','layout':'各階俯瞰','C-L3-dog-aerial':'L-3移設先の鳥瞰','C-L3-dog-ground':'芝生が分かる地上視点','C-L3-dog-gates':'二重ゲートと前室','C-dog-aerial':'旧ドッグラン位置・鳥瞰','C-dog-ground':'旧位置の撤去確認','C-dog-gates':'旧ゲート位置の撤去確認','B-old-west':'旧ES周辺の実画面','B-EV-hall':'既存B-K1 EVホール'}
items=[]
for c in cams:
 if not(out/'before'/f'{c["id"]}.jpg').exists()or not(out/'after'/f'{c["id"]}.jpg').exists():continue
 title=labels.get(c['id'],c['id'].rsplit('-',1)[0]+' '+labels.get(c['id'].rsplit('-',1)[-1],c['id']))
 items.append(dict(id=c['id'],title=title,eye=c['eye'],look=c['look'],projection='平行投影52m'if c.get('orthographic')else str(c['fov'])+'°'))
body='''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FIND YOURSELF v27 Review</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f1e9;color:#18343d;font:16px/1.8 system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:28px}header{background:#15313b;color:#faf8ed;padding:50px 32px}header div{max-width:1220px;margin:auto}h1{font-size:38px;line-height:1.35;margin:12px 0}h2{margin-top:52px;font-size:27px;border-bottom:2px solid #a8b6a6;padding-bottom:10px}h3{margin-top:30px}a{color:#19646f}header a{color:#d7e8da}nav{display:flex;gap:22px;flex-wrap:wrap}.lead{font-size:19px;max-width:950px}.note{border-left:4px solid #aa7843;background:#eae4d6;padding:15px 22px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:25px 0}.stats div{background:#fffdf7;padding:20px;border-radius:8px}.stats strong{font-size:30px;display:block}select,button{padding:10px;font:inherit;max-width:100%;background:white;border:1px solid #80968e;border-radius:5px}button{cursor:pointer}input[type=range]{width:100%}.compare{position:relative;aspect-ratio:16/9;overflow:hidden;background:#132d34;margin:15px 0}.compare img{width:100%;position:absolute;inset:0}.compare #new{clip-path:inset(0 0 0 50%)}.tag{position:absolute;bottom:10px;background:#15313bdd;color:white;padding:5px 14px;border-radius:5px}.right{right:10px}.left{left:10px}table{border-collapse:collapse;width:100%;background:#fffdf7;font-size:14px}td,th{padding:9px 12px;border-bottom:1px solid #d3d9ce;text-align:left}th{background:#dce4d8}.scroll{overflow:auto}.plans{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.plans img,.thumb img{width:100%;background:white;border:1px solid #c9d3c7}.thumb{display:inline-block;width:31%;margin:1%;vertical-align:top}summary{cursor:pointer}code{font-size:13px;overflow-wrap:anywhere}.pass{color:#2a6b44}footer{margin:40px 0;color:#62766d}@media(max-width:700px){main{padding:15px}h1{font-size:27px}.stats,.plans{grid-template-columns:1fr 1fr}.thumb{width:98%}header{padding:25px 18px}}</style>
<header><div><small>FIND YOURSELF / INDEPENDENT GODOT STUDY</small><h1>v27 建築設備の整合と仕上げ</h1><p class="lead">B館の旧・新ESを実測して区別し、連続ESを下から見ても完成した外装へ。C館のドッグランは建物と重なる舗装上から、実在するL-3緑地へ一体移設しました。</p><nav><a href="#visual">実画面比較</a><a href="#plans">平面図・断面図</a><a href="#inventory">設備の判断</a><a href="#tests">実歩行・回帰</a><a href="#limits">未完了・制限</a></nav></div></header><main>
<div class="note">独立検証版です。既存ゲーム本体への統合、未承認構造の正式採用、買い物シミュレーターのAI・会話・購入処理は行っていません。</div>
<div class="stats"><div><strong>15層</strong>A・B・C各5層を保持</div><div><strong>480店舗</strong>ID・内装・ブランドを保持</div><div><strong>43人</strong>既存試験NPCを保持</div><div><strong>6基</strong>B西連続ESの上り・下り</div></div>
<h2 id="visual">同じ位置・画角のGodot実画面</h2><p>1920×1080のGodotビューポートから直接保存した画像です。画像の塗り直し・合成・後処理はしていません。左右をスライダーで比較できます。鳥瞰では草葉を距離で省略し、地上では実際の短い草葉と地表の粒度を表示します。</p>
<select id="camera"></select> <button id="prev">前へ</button> <button id="next">次へ</button><div class="compare"><img id="old" alt="v26実画面"><img id="new" alt="v27実画面"><span class="tag left">v26 基準</span><span class="tag right">v27 改修後</span></div><input id="slider" type="range" min="0" max="100" value="50" aria-label="比較位置"><p id="pose"></p><p><a id="oldlink">v26の元画像</a> / <a id="newlink">v27の元画像</a></p>
<h3>通常起動・F4・F6の違い</h3><p>通常版とF6のES単独構造別案はB西の新連続ES6基を表示します。F4のC単独構造別案では、比較対象としてB館旧配置4基が復帰します。比較版だけに現れる旧設備を通常版の表示残りと混同しないよう、実入力イベントと画面の両方を記録しています。</p><div id="variants">'''
for folder in sorted(out.glob('after-*')):
 if folder.is_dir():
  body+=f'<h3>{esc(folder.name)}</h3>'
  for p in sorted(folder.glob('*.jpg')):body+=f'<a class="thumb" href="{folder.name}/{p.name}"><img loading="lazy" src="{folder.name}/{p.name}" alt="{esc(p.stem)}">{esc(p.stem)}</a>'
for p in sorted((out/'after').glob('*.jpg')):
 if not(out/'before'/p.name).exists():body+=f'<a class="thumb" href="after/{p.name}"><img loading="lazy" src="after/{p.name}" alt="{esc(p.stem)}">{esc(p.stem)}</a>'
body+='''</div><h2 id="plans">B館各階の平面図・ES断面・ドッグラン配置</h2><p>図面は保持した座標データから作成した説明図で、実画面とは区別しています。世界座標はm単位のx/y/z、館内図のローカルx/zには(+429,-46)を加えています。</p><div class="plans">'''
for p in sorted((out/'diagrams').glob('*.svg')):body+=f'<a href="diagrams/{p.name}"><img loading="lazy" src="diagrams/{p.name}" alt="{p.stem}">{p.stem}</a>'
body+='''</div><h2 id="inventory">採用・退役・維持の判断</h2><p>西側旧ES4基はv26ですでに退役設定でした。v27では退役を維持し、表示・ベルト制御・動く踏段の残存がないことと、旧地点の床24点を確認しました。中央・東側の独立ES8基、EV3基、階段3コアは別の動線として保持しています。新たなES/EVの移設や無条件撤去はありません。</p><p>新連続ESは1F→2F→3F→RFの3区間を上り下りで接続。B1は既存EVと階段が担当します。西側ESと最寄りEVの距離は約90mで、参考図の近接例を実測座標として扱っていません。</p><p><a href="data/equipment-inventory.csv">設備台帳CSV</a> / <a href="data/equipment-inventory.json">詳細JSON</a> / <a href="data/changed-equipment.json">変更ID・座標・理由</a></p><details><summary>B館全36レコードを表示</summary><div class="scroll"><table><tr><th>ID</th><th>種別</th><th>世界座標</th><th>判断</th></tr>'''
for row in inv['records']:body+=f'<tr><td>{esc(row["id"])}</td><td>{row["kind"]}</td><td>{esc(row["position"])}</td><td>{esc(row["decision"])}</td></tr>'
body+='''</table></div></details><h3>外装と芝生の仕様</h3><p>ESは既存機械ケースを残し、その外に幅1.76m・深さ0.91mの下面カセット、側板、水平端部を連続させました。12mmの目地、控えめな下面照明、実床で支持を確認した低頭空間のガラス区画を追加。支持ランプとベルト制御は変更していません。</p><p>ドッグランは(-1,-204)から(-77,-245)へ、柵・前室・二重門・ベンチ・サービス設備・案内を一体移設。24×19.2mの囲いの四隅はL-3緑地内です。緑地の輪郭を保った地表と2.5～6.5cmの短い草葉21,131本を制作し、水飲み・足洗い、ゴミ箱、ルール案内を周辺に配置しました。敷地地盤と薄い植栽面のセルフシャドウによる縞を抑え、建物・柵・設備から受ける影は保持しています。中央の既存庭園灯は西へ10.5m移し、44枚の衝突三角形も同時に動かしています。キッズ広場・キッチンカー・店舗は維持しました。</p>
<h2 id="tests">検証結果と元データ</h2><p>物理検証は60Hzの実CharacterBody3D、重力、move_and_slideを使った自動操作です。人によるプレイ試験とは区別しています。</p><table><tr><th>検証</th><th>結果</th><th>記録</th></tr>'''
checks=[('B西ES 上下6区間＋乗り継ぎ4経路','10/10 通過','movement.json'),('B西ES 入力なしのベルト乗車','6/6 到達','movement.json'),('旧ES地点の床','24/24 実床あり','movement.json'),('B館EV3基・各階乗降と帰還','18/18 通過','B-elevator-rides.json'),('新ドッグラン接近・二重門往復・芝生内歩行','6/6 通過、同時開放を拒否','dog-movement.json'),('芝生内の立位・マップ現在位置','12/12 干渉なし、L-3座標一致','dog-movement.json'),('既存出入口・自動ドア・案内・防災・480店舗・43NPC','18/18 合格','architecture-QA.json'),('M/F9/F11/F12/N/P等の実入力','12/12 合格','input-controls.json'),('F4/F6と通常版への復帰','4/4 合格','reference-scene-keys.json'),('店舗入口・主通路・什器支持・商品支持','480入口＋480主通路＋7287什器、70669/70669商品支持','retail-physics.json'),('読取専用カタログ','480店舗 / 74507商品 / 問題0','catalog-api.json'),('既存設備の立位確認','7241/7243。既知2件を継承','equipment-approaches.json')]
for a,b,c in checks:body+=f'<tr><td>{a}</td><td>{b}</td><td><a href="data/{c}">JSON</a></td></tr>'
body+='''</table><p>設備記録内の過去192経路は継承資料です。今回192件を歩き直したという意味ではありません。新規の実歩行件数は上表のES・EV・ドッグラン・出入口試験の範囲です。</p><h3>描画性能</h3><p>Godot 4.6.3 / Linux / OpenGL互換 / Mesa llvmpipeのソフトウェア描画で撮影。プロジェクトのForward+設定は保持しています。この環境ではSSR/SSILが使えず、Windows実GPUのFPSは未測定です。フレーム時間はCPU共用環境の参考値で、改善率や60fpsを保証しません。描画数と計測値はnative記録に収録しています。</p><div id="perf"></div>
<h2 id="limits">未完了・検証範囲</h2><ul><li>Windows実GPUでの性能測定、人による長時間の操作試験は未実施。</li><li>構造計算・防災法規・製造仕様の認証は未実施。未承認の構造候補は正式採用していません。</li><li>既知の設備立位2件（V22D-A1F-001-department_island-6402、V23-C3F-CE-1-capsule_corner-145）は既存版から継承し、今回の改修対象外として残っています。</li><li>ES区画外の全店舗・全方向の歩行や、あらゆる例外操作を網羅した保証ではありません。</li></ul><p><a href="data/user-reference.pdf">受領したv27参考図PDF</a> / <a href="data/REQUEST.md">受領した指示書</a>。参考図は設計意図の概念図として読み、配置は実プロジェクトから確認しました。実物写真をテクスチャや配布画像に流用していません。</p><h3>データ一覧</h3><div id="files">'''
for p in sorted(data.glob('*')):
 if p.is_file():body+=f'<a href="data/{p.name}">{esc(p.name)}</a><br>'
body+='''</div><footer>FIND YOURSELF v27 / Unsplit complete Godot source project + offline Review / No main-game integration.</footer></main><script>
const shots=SHOTS;const sel=document.querySelector('#camera');shots.forEach((s,i)=>{let o=document.createElement('option');o.value=i;o.textContent=s.title;sel.append(o)});function show(){let s=shots[+sel.value];document.querySelector('#old').src='before/'+s.id+'.jpg';document.querySelector('#new').src='after/'+s.id+'.jpg';document.querySelector('#oldlink').href='before/'+s.id+'.jpg';document.querySelector('#newlink').href='after/'+s.id+'.jpg';document.querySelector('#pose').textContent='位置 '+JSON.stringify(s.eye)+' / 注視点 '+JSON.stringify(s.look)+' / '+s.projection;}sel.onchange=show;document.querySelector('#slider').oninput=e=>document.querySelector('#new').style.clipPath='inset(0 0 0 '+e.target.value+'%)';document.querySelector('#prev').onclick=()=>{sel.value=(+sel.value+shots.length-1)%shots.length;show()};document.querySelector('#next').onclick=()=>{sel.value=(+sel.value+1)%shots.length;show()};sel.value=Math.max(0,shots.findIndex(s=>s.id==='B-1F-oblique'));show();
</script></html>'''.replace('SHOTS',json.dumps(items,ensure_ascii=False))
(out/'index.html').write_text(body)
